// 1. Obtener output (puede venir como string o como objeto)
let raw = $json.output ?? $json;

// 2. Parseo si es string
if (typeof raw === "string") {
  const jsonRegex = /(\{[\s\S]*\}|\[[\s\S]*\])/;
  const match = raw.match(jsonRegex);

  if (!match) throw new Error("No se encontró JSON válido");

  raw = JSON.parse(match[0]);
}

// 3. Detectar items
let items;

if (raw.output && Array.isArray(raw.output.items)) {
  items = raw.output.items;
} else if (Array.isArray(raw)) {
  items = raw;
} else if (typeof raw === "object" && raw !== null) {
  items = [raw];
} else {
  throw new Error("Formato no reconocido");
}

// 4. Traer categorías desde otro nodo
const categoriesMatch = $('Code in JavaScript').first().json.categoriesMatch || [];

// 5. IDs fallback
const DEFAULT_INCOME_CATEGORY_ID = "d9bb895c-add2-44d7-861f-5b4109d69c41";
const DEFAULT_EXPENSE_CATEGORY_ID = "b8ace44f-42bf-44cf-998f-6c4c7f9159e9";

// 6. Normalizador
function normalize(text) {
  return (text || "")
    .toString()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .trim();
}

// 7. Dirección esperada según tipo
function getExpectedDirection(tipo) {
  const t = normalize(tipo);

  if (t === "gasto") return "gasto";
  if (t === "ingreso") return "ingreso";
  if (t === "presupuesto") return "gasto";

  return null;
}

// 8. Normalizar dirección de categoría
function normalizeDirection(direction) {
  const d = normalize(direction);

  if (d === "gasto") return "gasto";
  if (d === "ingreso") return "ingreso";

  return null;
}

// 9. Fallback según tipo
function getFallbackCategoryId(tipo) {
  const t = normalize(tipo);

  if (t === "ingreso") return DEFAULT_INCOME_CATEGORY_ID;
  if (t === "gasto") return DEFAULT_EXPENSE_CATEGORY_ID;
  if (t === "presupuesto") return DEFAULT_EXPENSE_CATEGORY_ID;

  return null;
}

// 10. Crear mapas
const categoryMap = {};
const categoryMapByName = {};

for (const cat of categoriesMatch) {
  const nameKey = normalize(cat.name);
  const directionKey = normalizeDirection(cat.direction);

  if (!nameKey || !directionKey) continue;

  categoryMap[`${nameKey}__${directionKey}`] = {
    id: cat.id,
    name: cat.name,
    direction: directionKey
  };

  if (!categoryMapByName[nameKey]) {
    categoryMapByName[nameKey] = [];
  }

  categoryMapByName[nameKey].push({
    id: cat.id,
    name: cat.name,
    direction: directionKey
  });
}

// 11. Match
const result = items.map((item, operation_index) => {
  let categoryId = null;
  let matchedBy = null;
  let matchedCategoryDirection = null;

  const tipo = normalize(item.tipo);
  const categoria = normalize(item.categoria);
  const expectedDirection = getExpectedDirection(tipo);

  if (categoria && !["saludo", "basura", "balance"].includes(tipo)) {
    // Match exacto por nombre + dirección
    if (expectedDirection) {
      const exactMatch = categoryMap[`${categoria}__${expectedDirection}`];

      if (exactMatch) {
        categoryId = exactMatch.id;
        matchedBy = "name+direction";
        matchedCategoryDirection = exactMatch.direction;
      }
    }

    // Fallback por nombre solo si existe una única categoría
    // y además coincide con la dirección esperada
    if (!categoryId) {
      const candidates = categoryMapByName[categoria] || [];

      if (
        candidates.length === 1 &&
        candidates[0].direction === expectedDirection
      ) {
        categoryId = candidates[0].id;
        matchedBy = "name_only_unique_same_direction";
        matchedCategoryDirection = candidates[0].direction;
      }
    }
  }

  // Fallback final SOLO si no hubo match real
  if (!categoryId) {
    const fallbackCategoryId = getFallbackCategoryId(tipo);

    if (fallbackCategoryId) {
      categoryId = fallbackCategoryId;
      matchedBy = "default_fallback";
      matchedCategoryDirection = expectedDirection;
    }
  }

  return {
    json: {
      ...item,
      operation_index,
      category_id: categoryId,
      expected_direction: expectedDirection,
      matched_category_direction: matchedCategoryDirection,
      matched_by: matchedBy
    }
  };
});

return result;

