const rawOutput = $('Edit Fields1').first().json.output || "";

/**
 * 1) Extraer el primer bloque JSON válido que encuentre en todo el texto.
 *    Soporta:
 *     - ```json ... ```
 *     - ``` ... ```
 *     - Texto que contenga un {...} u [...]
 */
let jsonText = null;

// 1a. Buscar bloque ```json ... ```
let m = typeof rawOutput === "string"
  ? rawOutput.match(/```json\s*([\s\S]*?)\s*```/i)
  : null;

if (m && m[1]) {
  jsonText = m[1].trim();
} else if (typeof rawOutput === "string") {
  // 1b. Buscar cualquier bloque ``` ... ```
  m = rawOutput.match(/```\s*([\s\S]*?)\s*```/);
  if (m && m[1]) {
    jsonText = m[1].trim();
  } else {
    // 1c. Buscar el primer {...} o [...] dentro del texto
    m = rawOutput.match(/(\{[\s\S]*\}|\[[\s\S]*\])/);
    if (m && m[0]) {
      jsonText = m[0].trim();
    } else {
      // 1d. Intentar limpiar encabezados tipo "json\n[...]"
      const cleaned = rawOutput
        .replace(/^\s*json\s*/i, '')
        .replace(/^[`]+|[`]+$/g, '')
        .trim();

      m = cleaned.match(/(\{[\s\S]*\}|\[[\s\S]*\])/);
      if (m && m[0]) {
        jsonText = m[0].trim();
      }
    }
  }
}

// Si ya viene como objeto, no hace falta extraer texto
if (!jsonText && typeof rawOutput === "object" && rawOutput !== null) {
  jsonText = JSON.stringify(rawOutput);
}

if (!jsonText) {
  throw new Error("No se encontró ningún JSON en la salida del modelo.");
}

// 2) Parsear JSON
let parsed;
try {
  parsed = JSON.parse(jsonText);
} catch (err) {
  throw new Error(
    "Error al parsear el JSON extraído: " +
      err.message +
      "\nContenido extraído:\n" +
      jsonText
  );
}

// 3) Normalizar estructura a array real de transacciones
let items;

if (parsed?.output?.items && Array.isArray(parsed.output.items)) {
  items = parsed.output.items;
} else if (parsed?.items && Array.isArray(parsed.items)) {
  items = parsed.items;
} else if (Array.isArray(parsed)) {
  items = parsed;
} else if (parsed && typeof parsed === "object") {
  items = [parsed];
} else {
  throw new Error("El JSON parseado no tiene un formato válido.");
}

/** Utilidades **/

function normalizarTexto(texto = "") {
  return String(texto)
    .toLowerCase()
    .trim()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, '');
}

function parseValorToNumber(v) {
  if (v === null || v === undefined || v === "") return 0;
  if (typeof v === "number") return v;

  let s = String(v).trim();
  s = s.replace(/[\$\€\£\s]/g, '');

  const lastComma = s.lastIndexOf(',');
  const lastDot = s.lastIndexOf('.');

  if (lastComma > -1 && lastDot > -1) {
    if (lastComma > lastDot) {
      s = s.replace(/\./g, '').replace(/,/g, '.');
    } else {
      s = s.replace(/,/g, '');
    }
  } else if (s.indexOf(',') > -1 && s.indexOf('.') === -1) {
    s = s.replace(/,/g, '.');
  } else {
    s = s.replace(/,/g, '');
  }

  const n = parseFloat(s);
  return Number.isFinite(n) ? n : 0;
}

function formatNumber(n) {
  try {
    return new Intl.NumberFormat('es-CO', { maximumFractionDigits: 2 }).format(n);
  } catch (e) {
    return String(n);
  }
}

function emojiPorTipo(tipo = "") {
  const t = normalizarTexto(tipo);
  if (t === "gasto") return "💸";
  if (t === "ingreso") return "💰";
  if (t === "presupuesto") return "📊";
  return "🔄";
}

function emojiPorCategoria(nombre = "") {
  const c = normalizarTexto(nombre);
  const mapa = {
    salario: "💼",
    bonificaciones: "🎁",
    arriendo: "🏠",
    extras: "➕",
    regalos: "🎉",
    vivienda: "🏡",
    transporte: "🚗",
    educacion: "📚",
    "entretenimiento y ocio": "🎮",
    entretenimiento: "🎮",
    prestamos: "💳",
    alimentacion: "🍽️",
    "compras personales": "🛍️",
    salud: "💊",
    otros: "📦",
    seguros: "🛡️"
  };
  return mapa[c] || "📂";
}

// Limpia saltos y caracteres problemáticos dentro de cada campo
function cleanInlineText(value = "") {
  return String(value)
    .replace(/\r/g, "")
    .replace(/\n/g, " ")
    .replace(/\t/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

/** 4) Construir bloques de texto */
const bloques = items.map((item) => {
  const tipo = cleanInlineText(item.tipo || "");
  const rawValor = item.valor ?? item.monto ?? item.amount ?? "";
  const valorNum = parseValorToNumber(rawValor);
  const categoria = cleanInlineText(item.categoria || item.category || "");
  const descripcion = cleanInlineText(item.descripcion || item.description || "");

  const tipoEmoji = emojiPorTipo(tipo);
  const categoriaEmoji = emojiPorCategoria(categoria);

  const valorTexto = rawValor === "" ? "—" : formatNumber(valorNum);

  return `${tipoEmoji} Tipo: ${tipo || "—"}\n💵 Valor: ${valorTexto}\n${categoriaEmoji} Categoría: ${categoria || "—"}\n📌 Descripción: ${descripcion || "—"}`;
});

// Un renglón en blanco entre movimientos.
const resumenFinal = bloques.join("\n\n");

// 5) Devolver para n8n
return [
  {
    json: {
      resumen: resumenFinal,
    }
  }
];

