const formatNumber = (value) => {
  const num = Number(value || 0);
  const abs = Math.abs(num).toLocaleString('es-CO');
  return num < 0 ? `- $ ${abs}` : `$ ${abs}`;
};

const summary = $('Get a row1').first().json;
const incomeTotal = Number(summary.income_total || 0);
const expenseTotal = Number(summary.expense_total || 0);
const netTotal = Number(summary.net_total || 0);

// Saldo inicial = arrastre del mes anterior (meta.type = 'monthly_rollover'), igual que en la web
const initialBalance = $('Saldo inicial').all()
  .map((item) => item.json)
  .filter((tx) => tx && tx.amount !== undefined)
  .reduce((sum, tx) => sum + (tx.direction === 'ingreso' ? 1 : -1) * Number(tx.amount || 0), 0);
const availableBalance = initialBalance + netTotal;

const isPositiveBalance = netTotal > 0;
const isNegativeBalance = netTotal < 0;
const isZeroBalance = netTotal === 0;

let balanceIcon = '📈';
let balanceText = '🟰 *Vas en equilibrio, mantén el control*';

if (isPositiveBalance) {
  balanceIcon = '📈';
  balanceText = '🔥 *Vas muy bien, sigue así*';
} else if (isNegativeBalance) {
  balanceIcon = '📉';
  balanceText = '⚠️ *Ojo: este mes vas gastando más de lo que entra*';
} else if (isZeroBalance) {
  balanceIcon = '➖';
  balanceText = '🟰 *Vas justo, toca cuidar los próximos gastos*';
}

const message = `📊 *Así va tu mes*
━━━━━━━━━━━━━━
🏦 Saldo inicial: *${formatNumber(initialBalance)}*
💰 Ingresos: *${formatNumber(incomeTotal)}*
💸 Gastos: *${formatNumber(expenseTotal)}*
${balanceIcon} Balance del mes: *${formatNumber(netTotal)}*
💼 Disponible: *${formatNumber(availableBalance)}*
━━━━━━━━━━━━━━
${balanceText}`;

return [
  {
    json: {
      income_total_formatted: formatNumber(incomeTotal),
      expense_total_formatted: formatNumber(expenseTotal),
      net_total_formatted: formatNumber(netTotal),
      initial_balance_formatted: formatNumber(initialBalance),
      available_balance_formatted: formatNumber(availableBalance),
      is_positive_balance: isPositiveBalance,
      is_negative_balance: isNegativeBalance,
      is_zero_balance: isZeroBalance,
      message
    }
  }
];

